// Auto-generated base64 data URIs for the 3 selectable player ships.
// Embedding these directly avoids loading spaceships-for-player/*.png over
// file://, which taints the canvas and silently breaks getImageData()-based
// background stripping/cropping (data: URIs are never cross-origin, so this
// works identically whether the page is opened directly or served over HTTP).
const PLAYER_SHIP_DATA_URIS = [
  'data:image/jpeg;base64,',
  'data:image/webp;base64,',
  'data:image/png;base64,',
];
